#!/usr/bin/env node
'use strict';
// Generates the signed Universal Manifest fixtures used by the C++ tests in
// Teleport/test/.
//
// The fixtures MUST be produced here rather than in C++, because their whole
// purpose is to prove that the two implementations agree: a manifest this
// repository signs — using this repository's canonicaliser and its Ed25519
// stack — has to verify under Teleport/TeleportServer/ManifestVerify.cpp and
// Teleport/TeleportCore/Jcs.cpp. A fixture generated by the code under test
// would prove nothing.
//
// The signing key is derived from a fixed seed (the bytes 1..32) so the output
// is byte-stable across runs. That matters: a regenerated fixture whose
// signature value has changed, without an intended change to the manifest
// content, means the two canonicalisers have drifted. Investigate rather than
// pasting in the new value.
//
// Usage:
//   node tools/make-manifest-fixtures.js > ../Teleport/test/manifest_fixture.h

const crypto = require('node:crypto');

const jcs = require('../manifest/jcs.js');
const fx  = require('../test/helpers/manifest_fixtures.js');

const seed = Buffer.alloc(32);
for (let i = 0; i < 32; i++)
	seed[i] = i + 1;
const pkcs8 = Buffer.concat([Buffer.from('302e020100300506032b657004220420', 'hex'), seed]);
const privateKey = crypto.createPrivateKey({ key: pkcs8, format: 'der', type: 'pkcs8' });
const publicKey  = crypto.createPublicKey(privateKey);
const keyRef     = fx.didKeyFor(publicKey);

const ISSUED  = '2026-03-05T12:05:00Z';
const EXPIRES = '2036-03-05T12:05:00Z';
const AVATAR  = 'https://assets.example/avatars/beta.glb';

function avatarPointer(name = 'portableIdentity.avatar', target = AVATAR)
{
	return { '@type': 'um:Pointer', name, target };
}

function avatarFacet()
{
	return {
		'@id':		'urn:facet:avatarProfile',
		'@type':	['um:Facet'],
		name:		'avatarProfile',
		entity: {
			'@id':	'did:web:xr.example:users:beta#avatar',
			'@type': ['um:Entity', 'xr:AvatarProfile'],
			skeletonProfile: 'humanoid-v1',
			supportsFacialBlendShapes: true,
		},
	};
}

function avatarConsent()
{
	return {
		'@id':		'urn:consent:avatarProfile',
		'@type':	'um:Consent',
		facetRef:	'urn:facet:avatarProfile',
		scope:		['read', 'display'],
		purpose:	'avatar-presentation',
		grantedAt:	ISSUED,
		expiresAt:	EXPIRES,
	};
}

function envelope(overrides = {})
{
	const base = {
		'@context':			'https://universalmanifest.net/ns/v0.3',
		'@id':				'urn:uuid:6dfc40f2-8797-4f7b-a5f7-49d6a010f600',
		'@type':			['um:Manifest'],
		manifestVersion:	'0.3',
		subject:			'did:web:xr.example:users:beta',
		issuedAt:			ISSUED,
		expiresAt:			EXPIRES,
		pointers:			[avatarPointer()],
		facets:				[avatarFacet()],
		consents:			[avatarConsent()],
	};
	const merged = Object.assign(base, overrides);
	for (const key of Object.keys(merged))
	{
		if (merged[key] === undefined)
			delete merged[key];
	}
	return merged;
}

// The fixture set. Each is signed, so every one of them exercises the full
// verify path as well as whatever stage it is really about.
const FIXTURES = [
	{
		name:	'kSignedManifestJson',
		doc:	'The baseline: one avatar pointer, one requested facet, one consent for it.\n' +
				'Carries `somethingFromAFutureVersion`, a member no v0.3 consumer understands,\n' +
				'holding nested objects with unsorted keys and non-ASCII text. Unknown members\n' +
				'are covered by the signature, so this doubles as proof that forward\n' +
				'compatibility does not cost verifiability.',
		value:	envelope({
			somethingFromAFutureVersion: {
				nested:  [1, 2, { z: 1, a: 2 }],
				unicode: 'héllo €',
			},
		}),
	},
	{
		name:	'kManifestWithoutConsentJson',
		doc:	'The avatar pointer resolves, but the requested facet carries no consent.\n' +
				'Default-deny means the facet is withheld while the avatar still resolves —\n' +
				'partial acceptance is the normal outcome, not an error.',
		value:	envelope({ consents: [] }),
	},
	{
		name:	'kManifestWithoutAvatarPointerJson',
		doc:	'A manifest whose only pointer is something other than an avatar.',
		value:	envelope({ pointers: [avatarPointer('portableIdentity.wearables', 'https://assets.example/w.json')] }),
	},
	{
		name:	'kManifestRequiringTier1Json',
		doc:	'Declares requiredTrustTier 1, which needs verifiable presentations or\n' +
				'cross-DID binding. Tier 0 — signature-only — is all this implementation can\n' +
				'verify, so it must refuse rather than silently downgrade.',
		value:	envelope({ requiredTrustTier: 1 }),
	},
	{
		name:	'kManifestWithDeniedAvatarJson',
		doc:	'The subject has explicitly denied use of their avatar pointer.',
		value:	envelope({
			consents: [avatarConsent(), { '@type': 'um:Consent', name: 'portableIdentity.avatar', value: 'denied' }],
		}),
	},
	{
		name:	'kManifestWithRelativeTargetJson',
		doc:	'A pointer target relative to the manifest url, so a manifest may point at an\n' +
				'asset hosted beside it.',
		value:	envelope({ pointers: [avatarPointer('portableIdentity.avatar', 'avatars/me.glb')] }),
	},
	{
		name:	'kManifestWithSealedFacetJson',
		doc:	'The requested facet is encrypted and we have no key. It is acknowledged as\n' +
				'opaque and skipped — never grounds to reject the manifest.',
		value:	envelope({
			facets: [{
				'@id':				'urn:facet:avatarProfile',
				'@type':			['um:Facet'],
				name:				'avatarProfile',
				encryptionProfile:	'jwe-inline-v1',
				entity: { protected: 'eyJhbGciOiJFQ0RILUVTIn0', ciphertext: 'q1w2e3', iv: 'aXY', tag: 'dGFn' },
			}],
			consents: [],
		}),
	},
];

function cppStringLiteral(value)
{
	// A raw string literal keeps the JSON readable in the C++ source. The
	// delimiter has to be one the payload cannot contain.
	return 'R"JSON(' + JSON.stringify(value, null, 1) + ')JSON"';
}

const lines = [];
lines.push('#pragma once');
lines.push('');
lines.push('//! Signed Universal Manifest fixtures shared by the C++ manifest tests.');
lines.push('//!');
lines.push('//! GENERATED FILE — do not edit by hand. Regenerate with:');
lines.push('//!');
lines.push('//!   cd teleport-nodejs && node tools/make-manifest-fixtures.js \\');
lines.push('//!       > ../Teleport/test/manifest_fixture.h');
lines.push('//!');
lines.push('//! Every fixture is signed by the Node.js implementation using the Ed25519 key');
lines.push('//! whose seed is the bytes 1..32. Verifying them here proves that two');
lines.push('//! independent canonicalisers and two independent Ed25519 stacks agree');
lines.push('//! byte-for-byte — which is the only thing standing between a protocol change');
lines.push('//! and a fleet of clients whose manifests silently stop verifying.');
lines.push('//!');
lines.push('//! A regenerated fixture whose signature value changes without an intended');
lines.push('//! change to its content means the canonicalisers have drifted. Investigate');
lines.push('//! rather than pasting in the new value.');
lines.push('');
lines.push('namespace teleport');
lines.push('{');
lines.push('\tnamespace test');
lines.push('\t{');

for (const fixture of FIXTURES)
{
	const signed = fx.sign(fixture.value, privateKey, keyRef);
	for (const line of fixture.doc.split('\n'))
		lines.push('\t\t//! ' + line);
	lines.push('\t\tconstexpr const char *' + fixture.name + ' = ' + cppStringLiteral(signed) + ';');
	lines.push('');
}

lines.push('\t\tconstexpr const char *kFixtureDidKey    = "' + keyRef + '";');
lines.push('\t\tconstexpr const char *kFixtureSpkiB64   = "' + fx.spkiBase64For(publicKey) + '";');
lines.push('\t\tconstexpr const char *kFixtureAvatarUrl = "' + AVATAR + '";');
lines.push('');
lines.push('\t\t//! The UTF-8 byte length of the baseline fixture\'s canonical signing input.');
lines.push('\t\t//! Note the unit: this repository\'s canonicalize() returns a JS string, so');
lines.push('\t\t//! String.length would report fewer UTF-16 code units. What gets signed is');
lines.push('\t\t//! always the UTF-8 encoding (RFC 8785 §3.3).');
{
	const { signature, ...payload } = fx.sign(FIXTURES[0].value, privateKey, keyRef);
	void signature;
	lines.push('\t\tconstexpr size_t kFixtureSigningInputBytes = ' +
		Buffer.byteLength(jcs.canonicalize(payload), 'utf8') + ';');
}
lines.push('');
lines.push('\t\t//! Comfortably inside every fixture\'s validity window (2027-01-15).');
lines.push('\t\tconstexpr long long kFixtureNow = 1800000000LL;');
lines.push('\t}');
lines.push('}');
lines.push('');

process.stdout.write(lines.join('\n'));
